-- Mission 25 Part 11E: imported unit-cost, purchasing, vendor and recorded-balance observations.
-- Each dimension is independent. Currency, valuation and units must already be compatible.

CREATE TABLE public.canonical_external_material_cost_consents (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES public.organizations(id),
 source_key TEXT NOT NULL CHECK(source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'), purpose TEXT NOT NULL CHECK(purpose='imported_material_cost_vendor_availability_v1'),
 revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 10000), previous_id UUID, action TEXT NOT NULL CHECK(action IN('grant','revoke')),
 source_consent_id UUID NOT NULL, source_consent_revision BIGINT NOT NULL, source_consent_digest TEXT NOT NULL CHECK(source_consent_digest~'^[0-9a-f]{64}$'),
 actor_user_id UUID NOT NULL, membership_id UUID NOT NULL, auth_session_id UUID NOT NULL,
 source_scope JSONB NOT NULL CHECK(source_scope='["canonical_estimates","canonical_estimate_revisions","canonical_material_plans","canonical_external_material_import_records","canonical_external_material_reference_matches"]'::jsonb),
 consent_version TEXT NOT NULL CHECK(consent_version='m25-imported-material-cost-consent-v1'), reason TEXT NOT NULL CHECK(public.canonical_learning_text_valid(reason,2000)),
 request_key_hash TEXT NOT NULL CHECK(request_key_hash~'^[0-9a-f]{64}$'),request_digest TEXT NOT NULL CHECK(request_digest~'^[0-9a-f]{64}$'),canonical_digest TEXT NOT NULL CHECK(canonical_digest~'^[0-9a-f]{64}$'),created_at TIMESTAMPTZ NOT NULL DEFAULT transaction_timestamp(),
 UNIQUE(organization_id,source_key,purpose,revision),UNIQUE(organization_id,actor_user_id,request_key_hash),UNIQUE(organization_id,source_key,id),
 FOREIGN KEY(organization_id,source_key,previous_id)REFERENCES public.canonical_external_material_cost_consents(organization_id,source_key,id),
 FOREIGN KEY(organization_id,source_key,source_consent_id)REFERENCES public.canonical_external_material_import_consents(organization_id,source_key,id),
 FOREIGN KEY(organization_id,membership_id)REFERENCES public.organization_memberships(organization_id,id),FOREIGN KEY(organization_id,actor_user_id,auth_session_id)REFERENCES public.auth_sessions(organization_id,user_id,id),
 CHECK((revision=1 AND previous_id IS NULL)OR(revision>1 AND previous_id IS NOT NULL))
);

CREATE FUNCTION public.canonical_imported_material_cost_consent_projection(v public.canonical_external_material_cost_consents)RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT jsonb_build_object('id',v.id,'sourceKey',v.source_key,'purpose',v.purpose,'revision',v.revision,'previousId',v.previous_id,'action',v.action,'sourceConsent',jsonb_build_object('id',v.source_consent_id,'revision',v.source_consent_revision,'digest',rtrim(v.source_consent_digest)),'sourceScope',v.source_scope,'consentVersion',v.consent_version,'reason',v.reason,'digest',rtrim(v.canonical_digest),'createdAt',v.created_at) $$;

CREATE FUNCTION public.canonical_imported_material_cost_consent_read(org UUID,actor UUID,role_value TEXT,session_value UUID,source_value TEXT)RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE source_consent public.canonical_external_material_import_consents%ROWTYPE;current_row public.canonical_external_material_cost_consents%ROWTYPE;history JSONB;total BIGINT;active_value BOOLEAN;
BEGIN
 IF role_value IS NULL OR role_value NOT IN('owner','admin')THEN RAISE EXCEPTION 'Imported material cost review restricted' USING ERRCODE='42501';END IF;PERFORM public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,NULL,FALSE);
 IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' THEN RAISE EXCEPTION 'Material source invalid' USING ERRCODE='22023';END IF;
 SELECT * INTO source_consent FROM public.canonical_external_material_import_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;
 SELECT * INTO current_row FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;
 active_value:=source_consent.id IS NOT NULL AND source_consent.action='grant' AND current_row.id IS NOT NULL AND current_row.action='grant' AND current_row.source_consent_id=source_consent.id AND rtrim(current_row.source_consent_digest)=rtrim(source_consent.canonical_digest);
 SELECT count(*) INTO total FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value;
 SELECT COALESCE(jsonb_agg(public.canonical_imported_material_cost_consent_projection(x)ORDER BY revision DESC),'[]'::jsonb)INTO history FROM(SELECT * FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 20)x;
 RETURN jsonb_build_object('sourceKey',source_value,'active',active_value,'current',CASE WHEN current_row.id IS NULL THEN NULL ELSE public.canonical_imported_material_cost_consent_projection(current_row)END,'history',history,'total',total,'truncated',total>20,'blockedReason',CASE WHEN active_value THEN NULL WHEN source_consent.id IS NULL OR source_consent.action<>'grant' THEN 'External material source permission is not active.' WHEN current_row.id IS NOT NULL AND current_row.action='grant' THEN 'Cost and purchasing consent must be renewed for the current source permission.' ELSE 'Cost and purchasing consent is not active.' END);
END $$;

CREATE FUNCTION public.canonical_imported_material_cost_consent_mutate(org UUID,actor UUID,role_value TEXT,session_value UUID,csrf TEXT,key_value TEXT,source_value TEXT,body JSONB)RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE authority JSONB;source_consent public.canonical_external_material_import_consents%ROWTYPE;current_row public.canonical_external_material_cost_consents%ROWTYPE;replay public.canonical_external_material_cost_consents%ROWTYPE;inserted public.canonical_external_material_cost_consents%ROWTYPE;key_hash TEXT;request_hash TEXT;digest_value TEXT;next_revision BIGINT;active_value BOOLEAN;scope_value JSONB:='["canonical_estimates","canonical_estimate_revisions","canonical_material_plans","canonical_external_material_import_records","canonical_external_material_reference_matches"]'::jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'Serializable required' USING ERRCODE='25001';END IF;IF role_value IS NULL OR role_value NOT IN('owner','admin')THEN RAISE EXCEPTION 'Imported material cost review restricted' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.subscriptions WHERE organization_id=org FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable' USING ERRCODE='42501';END IF;authority:=public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,csrf,TRUE);
 IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR key_value IS NULL OR key_value!~'^[A-Za-z0-9._:-]{16,128}$' OR octet_length(body::text)>8192 OR public.canonical_field_evidence_object_keys_exact(body,ARRAY['action','expectedRevision','expectedDigest','reason','confirmed','confirmationVersion'])IS NOT TRUE OR body->>'action' NOT IN('grant','revoke') OR (body->>'expectedRevision')!~'^(0|[1-9][0-9]{0,3}|10000)$' OR body->>'expectedDigest'!~'^(none|[0-9a-f]{64})$' OR (((body->>'expectedRevision')::bigint=0)<>(body->>'expectedDigest'='none')) OR public.canonical_learning_text_valid(body->>'reason',2000)IS NOT TRUE OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR body->>'confirmationVersion' IS DISTINCT FROM 'm25-imported-material-cost-consent-v1' THEN RAISE EXCEPTION 'Imported material cost consent invalid' USING ERRCODE='22023';END IF;
 key_hash:=encode(sha256(convert_to(key_value,'UTF8')),'hex');request_hash:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'actorUserId',actor,'sourceKey',source_value,'body',body));PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':imported-material-cost-consent:'||source_value,0));
 SELECT * INTO replay FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND actor_user_id=actor AND request_key_hash=key_hash;IF FOUND THEN IF rtrim(replay.request_digest)<>request_hash THEN RAISE EXCEPTION 'Imported material cost consent key conflict' USING ERRCODE='23505';END IF;RETURN jsonb_build_object('consent',public.canonical_imported_material_cost_consent_projection(replay),'replayed',TRUE);END IF;
 SELECT * INTO source_consent FROM public.canonical_external_material_import_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1 FOR SHARE;IF source_consent.id IS NULL THEN RAISE EXCEPTION 'Material source permission unavailable' USING ERRCODE='40001';END IF;
 SELECT * INTO current_row FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF (body->>'expectedRevision')::bigint<>COALESCE(current_row.revision,0) OR body->>'expectedDigest' IS DISTINCT FROM COALESCE(rtrim(current_row.canonical_digest),'none') THEN RAISE EXCEPTION 'Imported material cost consent changed' USING ERRCODE='40001';END IF;
 active_value:=current_row.id IS NOT NULL AND current_row.action='grant' AND source_consent.action='grant' AND current_row.source_consent_id=source_consent.id AND rtrim(current_row.source_consent_digest)=rtrim(source_consent.canonical_digest);IF body->>'action'='grant' AND source_consent.action<>'grant' THEN RAISE EXCEPTION 'Material source permission inactive' USING ERRCODE='40001';END IF;IF body->>'action'='grant' AND active_value OR body->>'action'='revoke' AND(current_row.id IS NULL OR current_row.action<>'grant')THEN RAISE EXCEPTION 'Imported material cost consent action invalid' USING ERRCODE='22023';END IF;
 next_revision:=COALESCE(current_row.revision,0)+1;digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'sourceKey',source_value,'purpose','imported_material_cost_vendor_availability_v1','revision',next_revision,'previousId',current_row.id,'action',body->>'action','sourceConsentId',source_consent.id,'sourceConsentRevision',source_consent.revision,'sourceConsentDigest',rtrim(source_consent.canonical_digest),'actorUserId',actor,'membershipId',(authority->>'membershipId')::uuid,'sourceScope',scope_value,'reason',body->>'reason','requestDigest',request_hash));
 INSERT INTO public.canonical_external_material_cost_consents(organization_id,source_key,purpose,revision,previous_id,action,source_consent_id,source_consent_revision,source_consent_digest,actor_user_id,membership_id,auth_session_id,source_scope,consent_version,reason,request_key_hash,request_digest,canonical_digest)VALUES(org,source_value,'imported_material_cost_vendor_availability_v1',next_revision,current_row.id,body->>'action',source_consent.id,source_consent.revision,rtrim(source_consent.canonical_digest),actor,(authority->>'membershipId')::uuid,session_value,scope_value,'m25-imported-material-cost-consent-v1',body->>'reason',key_hash,request_hash,digest_value)RETURNING * INTO inserted;RETURN jsonb_build_object('consent',public.canonical_imported_material_cost_consent_projection(inserted),'replayed',FALSE);
END $$;

CREATE FUNCTION public.canonical_imported_material_cost_bindings_valid(value JSONB)RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE entry JSONB;lines TEXT[]:=ARRAY[]::text[];materials TEXT[]:=ARRAY[]::text[];
BEGIN IF jsonb_typeof(value)IS DISTINCT FROM 'array' OR jsonb_array_length(value)NOT BETWEEN 1 AND 20 THEN RETURN FALSE;END IF;FOR entry IN SELECT item FROM jsonb_array_elements(value)item LOOP
 IF public.canonical_field_evidence_object_keys_exact(entry,ARRAY['lineId','externalMaterialReference','externalVendorReference','externalInventoryLocationReference'])IS NOT TRUE OR (entry->>'lineId')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR (entry->>'externalMaterialReference')!~'^[!-~]{1,128}$' OR entry->>'lineId'=ANY(lines) OR entry->>'externalMaterialReference'=ANY(materials) THEN RETURN FALSE;END IF;
 IF entry->'externalVendorReference'<>'null'::jsonb AND(entry->>'externalVendorReference')!~'^[!-~]{1,128}$' THEN RETURN FALSE;END IF;IF entry->'externalInventoryLocationReference'<>'null'::jsonb AND(entry->>'externalInventoryLocationReference')!~'^[!-~]{1,128}$' THEN RETURN FALSE;END IF;lines:=array_append(lines,entry->>'lineId');materials:=array_append(materials,entry->>'externalMaterialReference');END LOOP;RETURN TRUE;END $$;

CREATE FUNCTION public.canonical_imported_material_cost_match(org UUID,source_value TEXT,consent_id_value UUID,kind_value TEXT,external_value TEXT,target_value TEXT)RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE match_row public.canonical_external_material_reference_matches%ROWTYPE;source_basis JSONB;target_basis JSONB;
BEGIN IF external_value IS NULL THEN RETURN NULL;END IF;SELECT * INTO match_row FROM public.canonical_external_material_reference_matches WHERE organization_id=org AND source_key=source_value AND consent_id=consent_id_value AND reference_kind=kind_value AND external_reference=external_value ORDER BY revision DESC LIMIT 1;IF match_row.id IS NULL OR match_row.action<>'link' OR (target_value IS NOT NULL AND match_row.target_reference<>target_value) THEN RETURN NULL;END IF;source_basis:=public.canonical_external_material_reference_source_basis(org,source_value,kind_value,external_value);target_basis:=public.canonical_external_material_reference_target_basis(org,kind_value,match_row.target_reference);IF source_basis IS NULL OR target_basis IS NULL OR rtrim(match_row.source_digest)<>source_basis->>'digest' OR rtrim(match_row.target_digest)<>target_basis->>'digest' THEN RETURN NULL;END IF;RETURN jsonb_build_object('id',match_row.id,'revision',match_row.revision,'digest',rtrim(match_row.canonical_digest),'kind',kind_value,'externalReference',external_value,'targetReference',match_row.target_reference,'sourceDigest',source_basis->>'digest','targetDigest',target_basis->>'digest');END $$;

CREATE FUNCTION public.canonical_imported_material_cost_basis(org UUID,source_value TEXT,estimate UUID,job_reference_value TEXT,bindings JSONB)RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE source_consent public.canonical_external_material_import_consents%ROWTYPE;estimate_row public.canonical_estimates%ROWTYPE;revision_row public.canonical_estimate_revisions%ROWTYPE;plan_row public.canonical_material_plans%ROWTYPE;component JSONB;sorted_bindings JSONB;binding JSONB;line JSONB;job_match JSONB;material_match JSONB;vendor_match JSONB;location_match JSONB;matches JSONB:='[]'::jsonb;records JSONB;result_lines JSONB:='[]'::jsonb;manifest JSONB;plan_count INT;binding_count INT;planned NUMERIC;plan_price NUMERIC;unit_cost_count INT;unit_cost_bad INT;unit_cost_amount NUMERIC;purchase_count INT;purchase_unit_bad INT;purchase_vendor_bad INT;purchase_qty NUMERIC;line_total_count INT;line_total_bad INT;line_total_amount NUMERIC;vendor_record_count INT;vendor_evidence_count INT;balance_count INT;balance_unit_bad INT;balance_qty NUMERIC;balance_at TIMESTAMPTZ;vendor_target TEXT;unit_cost JSONB;purchase JSONB;vendor JSONB;availability JSONB;available_dims INT:=0;material_targets TEXT[]:=ARRAY[]::text[];
BEGIN
 IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR job_reference_value IS NULL OR job_reference_value!~'^[!-~]{1,128}$' OR public.canonical_imported_material_cost_bindings_valid(bindings)IS NOT TRUE THEN RAISE EXCEPTION 'Imported material cost input invalid' USING ERRCODE='22023';END IF;SELECT COALESCE(jsonb_agg(value ORDER BY value->>'lineId'),'[]'::jsonb)INTO sorted_bindings FROM jsonb_array_elements(bindings)value;
 SELECT * INTO source_consent FROM public.canonical_external_material_import_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;IF source_consent.id IS NULL OR source_consent.action<>'grant' THEN RAISE EXCEPTION 'Material source permission unavailable' USING ERRCODE='P0002';END IF;
 SELECT * INTO estimate_row FROM public.canonical_estimates WHERE organization_id=org AND id=estimate;IF NOT FOUND THEN RAISE EXCEPTION 'Estimate unavailable' USING ERRCODE='P0002';END IF;SELECT * INTO revision_row FROM public.canonical_estimate_revisions WHERE organization_id=org AND estimate_id=estimate ORDER BY revision DESC LIMIT 1;component:=public.canonical_estimate_revision_components(revision_row)->'material';IF component->>'kind' IS DISTINCT FROM 'plan' THEN RAISE EXCEPTION 'Adopted material plan required' USING ERRCODE='P0002';END IF;SELECT * INTO plan_row FROM public.canonical_material_plans WHERE organization_id=org AND id=(component->>'id')::uuid AND revision=(component->>'revision')::bigint AND digest=component->>'digest' AND action='save';IF NOT FOUND THEN RAISE EXCEPTION 'Adopted material plan required' USING ERRCODE='P0002';END IF;
 job_match:=public.canonical_imported_material_cost_match(org,source_value,source_consent.id,'job',job_reference_value,estimate::text);IF job_match IS NULL THEN RAISE EXCEPTION 'Current reviewed job match required' USING ERRCODE='P0002';END IF;
 plan_count:=jsonb_array_length(plan_row.inputs->'lines');binding_count:=jsonb_array_length(bindings);IF plan_count<>binding_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(plan_row.inputs->'lines')p WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(bindings)b WHERE b->>'lineId'=p->>'lineId'))THEN RAISE EXCEPTION 'Every planned line needs one exact material binding' USING ERRCODE='P0002';END IF;
 IF EXISTS(WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_material_import_records r JOIN public.canonical_external_material_import_runs run ON run.organization_id=r.organization_id AND run.source_key=r.source_key AND run.id=r.import_run_id WHERE r.organization_id=org AND r.source_key=source_value AND run.consent_id=source_consent.id ORDER BY r.external_record_id,r.revision DESC)SELECT 1 FROM current_records r WHERE r.state='active' AND r.record_type IN('purchase','vendor_cost') AND r.job_reference=job_reference_value AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(bindings)b WHERE b->>'externalMaterialReference'=r.material_reference))THEN RAISE EXCEPTION 'Current job cost records exceed the exact planned material bindings' USING ERRCODE='P0002';END IF;
 FOR binding IN SELECT value FROM jsonb_array_elements(sorted_bindings) LOOP
  SELECT value INTO line FROM jsonb_array_elements(plan_row.inputs->'lines')WHERE value->>'lineId'=binding->>'lineId';planned:=CASE WHEN line->>'unit'='ea' THEN ceil((line->>'quantity')::numeric*(1+(line->>'wastePercent')::numeric/100))ELSE ceil((line->>'quantity')::numeric*(1+(line->>'wastePercent')::numeric/100)*1000000)/1000000 END;plan_price:=(line->>'unitPrice')::numeric;
  material_match:=public.canonical_imported_material_cost_match(org,source_value,source_consent.id,'material',binding->>'externalMaterialReference',NULL);IF material_match IS NULL THEN RAISE EXCEPTION 'Current reviewed material match required' USING ERRCODE='P0002';END IF;IF material_match->>'targetReference'=ANY(material_targets)THEN RAISE EXCEPTION 'Each plan line needs one distinct reviewed material target' USING ERRCODE='P0002';END IF;material_targets:=array_append(material_targets,material_match->>'targetReference');
  vendor_target:=CASE WHEN line#>>'{evidence,kind}'='supplier_quote' THEN public.canonical_material_source_identity_text(line#>>'{evidence,issuer}') ELSE NULL END;vendor_match:=NULL;location_match:=NULL;
  IF binding->>'externalVendorReference' IS NOT NULL THEN IF vendor_target IS NULL THEN RAISE EXCEPTION 'Adopted line has no reviewed supplier target' USING ERRCODE='P0002';END IF;vendor_match:=public.canonical_imported_material_cost_match(org,source_value,source_consent.id,'vendor',binding->>'externalVendorReference',vendor_target);IF vendor_match IS NULL THEN RAISE EXCEPTION 'Current reviewed vendor match required' USING ERRCODE='P0002';END IF;END IF;
  IF binding->>'externalInventoryLocationReference' IS NOT NULL THEN location_match:=public.canonical_imported_material_cost_match(org,source_value,source_consent.id,'inventory_location',binding->>'externalInventoryLocationReference',NULL);IF location_match IS NULL THEN RAISE EXCEPTION 'Current reviewed inventory location match required' USING ERRCODE='P0002';END IF;END IF;
  matches:=matches||jsonb_build_array(jsonb_build_object('lineId',binding->>'lineId','material',material_match,'vendor',vendor_match,'inventoryLocation',location_match));
  WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_material_import_records r JOIN public.canonical_external_material_import_runs run ON run.organization_id=r.organization_id AND run.source_key=r.source_key AND run.id=r.import_run_id WHERE r.organization_id=org AND r.source_key=source_value AND run.consent_id=source_consent.id ORDER BY r.external_record_id,r.revision DESC),costs AS(SELECT * FROM current_records WHERE state='active' AND record_type IN('vendor_cost','purchase') AND material_reference=binding->>'externalMaterialReference' AND (job_reference IS NULL OR job_reference=job_reference_value) AND vendor_reference IS NOT DISTINCT FROM binding->>'externalVendorReference' AND normalized_evidence#>>'{cost,valuation}'='unit_cost') SELECT count(DISTINCT normalized_evidence#>>'{cost,amount}'),count(*)FILTER(WHERE normalized_evidence#>>'{quantity,unit}'<>line->>'unit' OR normalized_evidence#>>'{cost,currency}'<>estimate_row.currency),min((normalized_evidence#>>'{cost,amount}')::numeric) FILTER(WHERE normalized_evidence#>>'{quantity,unit}'=line->>'unit' AND normalized_evidence#>>'{cost,currency}'=estimate_row.currency),count(*) FILTER(WHERE normalized_evidence#>>'{quantity,unit}'=line->>'unit' AND normalized_evidence#>>'{cost,currency}'=estimate_row.currency) INTO unit_cost_count,unit_cost_bad,unit_cost_amount,vendor_record_count FROM costs;
  IF vendor_record_count>0 AND unit_cost_bad=0 AND unit_cost_count=1 THEN unit_cost:=jsonb_build_object('status','compared','recordedUnitCost',unit_cost_amount::text,'plannedUnitCost',plan_price::text,'currency',estimate_row.currency,'unit',line->>'unit','varianceAmount',round(unit_cost_amount-plan_price,6)::text,'unavailableReason',NULL);available_dims:=available_dims+1;ELSE unit_cost:=jsonb_build_object('status','unavailable','recordedUnitCost',NULL,'plannedUnitCost',plan_price::text,'currency',estimate_row.currency,'unit',line->>'unit','varianceAmount',NULL,'unavailableReason',CASE WHEN binding->>'externalVendorReference' IS NULL THEN 'A reviewed vendor binding is required for unit-cost evidence.' WHEN vendor_record_count=0 AND unit_cost_bad=0 THEN 'No compatible same-currency unit-cost record is available in the planned unit.' WHEN unit_cost_bad>0 THEN 'A recorded unit cost uses a different unit or currency; no conversion is inferred.' ELSE 'More than one current unit cost is recorded; review the source before comparison.' END);END IF;
  WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_material_import_records r JOIN public.canonical_external_material_import_runs run ON run.organization_id=r.organization_id AND run.source_key=r.source_key AND run.id=r.import_run_id WHERE r.organization_id=org AND r.source_key=source_value AND run.consent_id=source_consent.id ORDER BY r.external_record_id,r.revision DESC),p AS(SELECT * FROM current_records WHERE state='active' AND record_type='purchase' AND job_reference=job_reference_value AND material_reference=binding->>'externalMaterialReference')SELECT count(*),count(*)FILTER(WHERE normalized_evidence#>>'{quantity,unit}'<>line->>'unit'),count(*)FILTER(WHERE vendor_reference IS DISTINCT FROM binding->>'externalVendorReference'),COALESCE(sum((normalized_evidence#>>'{quantity,value}')::numeric)FILTER(WHERE normalized_evidence#>>'{quantity,unit}'=line->>'unit'),0),count(*)FILTER(WHERE normalized_evidence#>>'{cost,valuation}'='line_total'),count(*)FILTER(WHERE normalized_evidence#>>'{cost,valuation}'<>'line_total' OR normalized_evidence#>>'{cost,currency}'<>estimate_row.currency),COALESCE(sum((normalized_evidence#>>'{cost,amount}')::numeric)FILTER(WHERE normalized_evidence#>>'{cost,valuation}'='line_total' AND normalized_evidence#>>'{cost,currency}'=estimate_row.currency),0) INTO purchase_count,purchase_unit_bad,purchase_vendor_bad,purchase_qty,line_total_count,line_total_bad,line_total_amount FROM p;
  purchase:=jsonb_build_object('quantity',CASE WHEN purchase_count>0 AND purchase_unit_bad=0 AND purchase_vendor_bad=0 THEN jsonb_build_object('status','compared','recordedQuantity',round(purchase_qty,6)::text,'plannedQuantity',planned::text,'unit',line->>'unit','varianceQuantity',round(purchase_qty-planned,6)::text,'unavailableReason',NULL)ELSE jsonb_build_object('status','unavailable','recordedQuantity',NULL,'plannedQuantity',planned::text,'unit',line->>'unit','varianceQuantity',NULL,'unavailableReason',CASE WHEN purchase_count=0 THEN 'No job purchase is recorded for this material and vendor.' WHEN purchase_vendor_bad>0 THEN 'Job purchases use more than the one reviewed vendor binding; review the source before comparison.' ELSE 'Recorded purchase units do not match the planned unit.' END)END,'lineTotal',CASE WHEN purchase_count>0 AND purchase_vendor_bad=0 AND line_total_count=purchase_count AND line_total_bad=0 THEN jsonb_build_object('status','recorded','amount',round(line_total_amount,6)::text,'currency',estimate_row.currency,'valuation','line_total','unavailableReason',NULL)ELSE jsonb_build_object('status','unavailable','amount',NULL,'currency',NULL,'valuation',NULL,'unavailableReason',CASE WHEN purchase_count=0 THEN 'No job purchase is recorded for this material and vendor.' WHEN purchase_vendor_bad>0 THEN 'Job purchases use more than the one reviewed vendor binding; review the source before comparison.' ELSE 'A purchase total is available only when every purchase has the same line-total valuation and plan currency.' END)END);IF purchase_count>0 AND purchase_unit_bad=0 AND purchase_vendor_bad=0 THEN available_dims:=available_dims+1;END IF;
  WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_material_import_records r JOIN public.canonical_external_material_import_runs run ON run.organization_id=r.organization_id AND run.source_key=r.source_key AND run.id=r.import_run_id WHERE r.organization_id=org AND r.source_key=source_value AND run.consent_id=source_consent.id ORDER BY r.external_record_id,r.revision DESC)SELECT count(*)INTO vendor_evidence_count FROM current_records WHERE state='active' AND record_type IN('purchase','vendor_cost') AND material_reference=binding->>'externalMaterialReference' AND (job_reference IS NULL OR job_reference=job_reference_value) AND vendor_reference IS NOT DISTINCT FROM binding->>'externalVendorReference';
  vendor:=CASE WHEN vendor_match IS NULL THEN jsonb_build_object('status','unavailable','reviewedTarget',NULL,'unavailableReason','No reviewed vendor binding is recorded for this plan line.') WHEN purchase_vendor_bad>0 THEN jsonb_build_object('status','unavailable','reviewedTarget',vendor_target,'unavailableReason','Job purchases use more than the one reviewed vendor binding; vendor attribution needs review.') WHEN vendor_evidence_count=0 THEN jsonb_build_object('status','unavailable','reviewedTarget',vendor_target,'unavailableReason','No current purchasing or cost record uses the reviewed vendor reference.') ELSE jsonb_build_object('status','recorded','reviewedTarget',vendor_target,'evidenceRecordCount',vendor_evidence_count,'verificationBoundary','This is company-reviewed vendor lineage, not independent supplier verification.','unavailableReason',NULL)END;IF vendor->>'status'='recorded' THEN available_dims:=available_dims+1;END IF;
  IF binding->>'externalInventoryLocationReference' IS NULL THEN availability:=jsonb_build_object('status','unavailable','recordedBalance',NULL,'recordedAt',NULL,'unavailableReason','A reviewed inventory location binding is required.');ELSE WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_material_import_records r JOIN public.canonical_external_material_import_runs run ON run.organization_id=r.organization_id AND run.source_key=r.source_key AND run.id=r.import_run_id WHERE r.organization_id=org AND r.source_key=source_value AND run.consent_id=source_consent.id ORDER BY r.external_record_id,r.revision DESC),b AS(SELECT * FROM current_records WHERE state='active' AND record_type='inventory_balance' AND material_reference=binding->>'externalMaterialReference' AND location_reference=binding->>'externalInventoryLocationReference')SELECT count(*),count(*)FILTER(WHERE normalized_evidence#>>'{quantity,unit}'<>line->>'unit'),min((normalized_evidence#>>'{quantity,value}')::numeric),min(occurred_at) INTO balance_count,balance_unit_bad,balance_qty,balance_at FROM b;IF balance_count=1 AND balance_unit_bad=0 THEN availability:=jsonb_build_object('status','recorded_balance','recordedBalance',balance_qty::text,'plannedQuantity',planned::text,'unit',line->>'unit','recordedAt',balance_at,'coverageCode',CASE WHEN balance_qty>=planned THEN 'recorded_balance_covers_plan' ELSE 'recorded_balance_below_plan' END,'currentAvailabilityConfirmed',FALSE,'unavailableReason',NULL);available_dims:=available_dims+1;ELSE availability:=jsonb_build_object('status','unavailable','recordedBalance',NULL,'recordedAt',NULL,'currentAvailabilityConfirmed',FALSE,'unavailableReason',CASE WHEN balance_count=0 THEN 'No inventory balance is recorded for the reviewed material and location.' WHEN balance_count>1 THEN 'More than one current balance record exists; review the source before comparison.' ELSE 'The recorded balance unit does not match the planned unit.' END);END IF;END IF;
  result_lines:=result_lines||jsonb_build_array(jsonb_build_object('lineId',binding->>'lineId','material',line->>'material','externalMaterialReference',binding->>'externalMaterialReference','plannedQuantity',planned::text,'plannedUnit',line->>'unit','unitCost',unit_cost,'purchasing',purchase,'vendor',vendor,'recordedBalance',availability));
 END LOOP;
 WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_material_import_records r JOIN public.canonical_external_material_import_runs run ON run.organization_id=r.organization_id AND run.source_key=r.source_key AND run.id=r.import_run_id WHERE r.organization_id=org AND r.source_key=source_value AND run.consent_id=source_consent.id ORDER BY r.external_record_id,r.revision DESC),selected AS(SELECT r.* FROM current_records r WHERE state='active' AND((record_type IN('purchase','vendor_cost')AND job_reference=job_reference_value)OR(record_type='vendor_cost'AND job_reference IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(bindings)b WHERE b->>'externalMaterialReference'=r.material_reference AND b->>'externalVendorReference' IS NOT DISTINCT FROM r.vendor_reference))OR(record_type='inventory_balance'AND EXISTS(SELECT 1 FROM jsonb_array_elements(bindings)b WHERE b->>'externalMaterialReference'=r.material_reference AND b->>'externalInventoryLocationReference' IS NOT DISTINCT FROM r.location_reference))))SELECT COALESCE(jsonb_agg(public.canonical_external_material_record_projection(r)ORDER BY external_record_id),'[]'::jsonb)INTO records FROM selected r;
 manifest:=jsonb_build_object('estimate',jsonb_build_object('id',estimate_row.id,'digest',rtrim(estimate_row.snapshot_digest),'currency',estimate_row.currency),'estimateRevision',jsonb_build_object('id',revision_row.id,'revision',revision_row.revision,'digest',revision_row.digest),'materialPlan',jsonb_build_object('id',plan_row.id,'revision',plan_row.revision,'digest',plan_row.digest,'calculationVersion',plan_row.calculation_version),'sourceConsent',jsonb_build_object('id',source_consent.id,'revision',source_consent.revision,'digest',rtrim(source_consent.canonical_digest)),'jobMatch',job_match,'referenceMatches',matches,'bindings',sorted_bindings,'importedRecords',records);
 RETURN jsonb_build_object('sourceManifest',manifest,'sourceDigest',public.canonical_completion_digest(manifest),'result',jsonb_build_object('lineCount',plan_count,'availableDimensionCount',available_dims,'lines',result_lines),'scopeNote','Unit cost, purchasing, reviewed vendor lineage and recorded inventory balance are separate dimensions. Missing or incompatible evidence remains unavailable. Currency, valuation and unit conversions are not inferred.','adoptionBoundary','A recorded balance describes only its source time and does not confirm current availability. Review this evidence before changing material assumptions. No estimate, price, purchase, vendor, inventory, job, plan or policy was changed.');
END $$;

CREATE TABLE public.canonical_external_material_cost_observations (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id),source_key TEXT NOT NULL,estimate_id UUID NOT NULL,external_job_reference TEXT NOT NULL CHECK(external_job_reference~'^[!-~]{1,128}$'),revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 10000),previous_id UUID,consent_id UUID NOT NULL,consent_revision BIGINT NOT NULL,consent_digest TEXT NOT NULL CHECK(consent_digest~'^[0-9a-f]{64}$'),source_manifest JSONB NOT NULL CHECK(jsonb_typeof(source_manifest)='object' AND octet_length(source_manifest::text)<=1048576),source_digest TEXT NOT NULL CHECK(source_digest~'^[0-9a-f]{64}$'),result JSONB NOT NULL CHECK(jsonb_typeof(result)='object' AND octet_length(result::text)<=524288),scope_note TEXT NOT NULL CHECK(public.canonical_learning_text_valid(scope_note,1000)),adoption_boundary TEXT NOT NULL CHECK(public.canonical_learning_text_valid(adoption_boundary,1000)),actor_user_id UUID NOT NULL,membership_id UUID NOT NULL,auth_session_id UUID NOT NULL,reason TEXT NOT NULL CHECK(public.canonical_learning_text_valid(reason,2000)),confirmed BOOLEAN NOT NULL CHECK(confirmed),confirmation_version TEXT NOT NULL CHECK(confirmation_version='m25-imported-material-cost-observation-v1'),calculation_version TEXT NOT NULL CHECK(calculation_version='m25-imported-material-cost-observation-v1'),request_key_hash TEXT NOT NULL CHECK(request_key_hash~'^[0-9a-f]{64}$'),request_digest TEXT NOT NULL CHECK(request_digest~'^[0-9a-f]{64}$'),canonical_digest TEXT NOT NULL CHECK(canonical_digest~'^[0-9a-f]{64}$'),created_at TIMESTAMPTZ NOT NULL DEFAULT transaction_timestamp(),UNIQUE(organization_id,source_key,estimate_id,external_job_reference,revision),UNIQUE(organization_id,source_key,estimate_id,external_job_reference,source_digest,consent_id),UNIQUE(organization_id,actor_user_id,request_key_hash),UNIQUE(organization_id,source_key,id),FOREIGN KEY(organization_id,estimate_id)REFERENCES public.canonical_estimates(organization_id,id),FOREIGN KEY(organization_id,source_key,previous_id)REFERENCES public.canonical_external_material_cost_observations(organization_id,source_key,id),FOREIGN KEY(organization_id,source_key,consent_id)REFERENCES public.canonical_external_material_cost_consents(organization_id,source_key,id),FOREIGN KEY(organization_id,membership_id)REFERENCES public.organization_memberships(organization_id,id),FOREIGN KEY(organization_id,actor_user_id,auth_session_id)REFERENCES public.auth_sessions(organization_id,user_id,id),CHECK((revision=1 AND previous_id IS NULL)OR(revision>1 AND previous_id IS NOT NULL)),CHECK(public.canonical_field_evidence_object_keys_exact(source_manifest,ARRAY['estimate','estimateRevision','materialPlan','sourceConsent','jobMatch','referenceMatches','bindings','importedRecords'])),CHECK(rtrim(source_digest)=public.canonical_completion_digest(source_manifest))
);
CREATE TRIGGER canonical_external_material_cost_consents_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON public.canonical_external_material_cost_consents FOR EACH STATEMENT EXECUTE FUNCTION public.canonical_external_material_immutable();
CREATE TRIGGER canonical_external_material_cost_observations_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON public.canonical_external_material_cost_observations FOR EACH STATEMENT EXECUTE FUNCTION public.canonical_external_material_immutable();
CREATE FUNCTION public.canonical_imported_material_cost_projection(v public.canonical_external_material_cost_observations)RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT jsonb_build_object('id',v.id,'sourceKey',v.source_key,'estimateId',v.estimate_id,'externalJobReference',v.external_job_reference,'revision',v.revision,'previousId',v.previous_id,'consent',jsonb_build_object('id',v.consent_id,'revision',v.consent_revision,'digest',rtrim(v.consent_digest)),'sourceManifest',v.source_manifest,'sourceDigest',rtrim(v.source_digest),'result',v.result,'scopeNote',v.scope_note,'adoptionBoundary',v.adoption_boundary,'reason',v.reason,'confirmationVersion',v.confirmation_version,'calculationVersion',v.calculation_version,'digest',rtrim(v.canonical_digest),'createdAt',v.created_at) $$;

CREATE FUNCTION public.canonical_imported_material_cost_observe(org UUID,actor UUID,role_value TEXT,session_value UUID,csrf TEXT,key_value TEXT,source_value TEXT,estimate UUID,job_reference_value TEXT,expected_consent_revision BIGINT,expected_consent_digest TEXT,bindings JSONB,reason_value TEXT,confirmed_value BOOLEAN,confirmation_version_value TEXT)RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE authority JSONB;source_consent public.canonical_external_material_import_consents%ROWTYPE;consent_row public.canonical_external_material_cost_consents%ROWTYPE;current_row public.canonical_external_material_cost_observations%ROWTYPE;replay public.canonical_external_material_cost_observations%ROWTYPE;inserted public.canonical_external_material_cost_observations%ROWTYPE;basis JSONB;key_hash TEXT;request_hash TEXT;digest_value TEXT;next_revision BIGINT;fresh BOOLEAN;
BEGIN IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'Serializable required' USING ERRCODE='25001';END IF;IF role_value IS NULL OR role_value NOT IN('owner','admin')THEN RAISE EXCEPTION 'Imported material cost review restricted' USING ERRCODE='42501';END IF;authority:=public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,csrf,TRUE);IF key_value IS NULL OR key_value!~'^[A-Za-z0-9._:-]{16,128}$' OR expected_consent_revision NOT BETWEEN 1 AND 10000 OR expected_consent_digest!~'^[0-9a-f]{64}$' OR public.canonical_imported_material_cost_bindings_valid(bindings)IS NOT TRUE OR public.canonical_learning_text_valid(reason_value,2000)IS NOT TRUE OR confirmed_value IS DISTINCT FROM TRUE OR confirmation_version_value IS DISTINCT FROM 'm25-imported-material-cost-observation-v1' THEN RAISE EXCEPTION 'Imported material cost input invalid' USING ERRCODE='22023';END IF;
 key_hash:=encode(sha256(convert_to(key_value,'UTF8')),'hex');request_hash:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'actorUserId',actor,'sourceKey',source_value,'estimateId',estimate,'externalJobReference',job_reference_value,'consentRevision',expected_consent_revision,'consentDigest',expected_consent_digest,'bindings',bindings,'reason',reason_value,'confirmed',confirmed_value,'confirmationVersion',confirmation_version_value));PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':imported-material-cost:'||source_value||':'||estimate::text||':'||job_reference_value,0));
 SELECT * INTO replay FROM public.canonical_external_material_cost_observations WHERE organization_id=org AND actor_user_id=actor AND request_key_hash=key_hash;IF FOUND THEN IF rtrim(replay.request_digest)<>request_hash THEN RAISE EXCEPTION 'Imported material cost key conflict' USING ERRCODE='23505';END IF;SELECT * INTO source_consent FROM public.canonical_external_material_import_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;SELECT * INTO consent_row FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;IF source_consent.id IS NULL OR source_consent.action<>'grant' OR consent_row.id IS NULL OR consent_row.action<>'grant' OR consent_row.source_consent_id<>source_consent.id OR rtrim(consent_row.source_consent_digest)<>rtrim(source_consent.canonical_digest) OR replay.consent_id<>consent_row.id THEN RETURN jsonb_build_object('observation',jsonb_build_object('id',replay.id,'revision',replay.revision,'fresh',FALSE,'advisoryAvailable',FALSE,'hiddenByConsent',TRUE),'replayed',TRUE);END IF;BEGIN basis:=public.canonical_imported_material_cost_basis(org,source_value,estimate,job_reference_value,replay.source_manifest->'bindings');fresh:=rtrim(replay.source_digest)=basis->>'sourceDigest';EXCEPTION WHEN SQLSTATE 'P0002' THEN fresh:=FALSE;END;RETURN jsonb_build_object('observation',public.canonical_imported_material_cost_projection(replay)||jsonb_build_object('fresh',fresh,'advisoryAvailable',fresh AND (replay.result->>'availableDimensionCount')::int>0,'result',CASE WHEN fresh THEN replay.result ELSE jsonb_build_object('availableDimensionCount',0,'lines','[]'::jsonb)END),'replayed',TRUE);END IF;
 SELECT * INTO source_consent FROM public.canonical_external_material_import_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1 FOR SHARE;SELECT * INTO consent_row FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1 FOR SHARE;IF source_consent.id IS NULL OR source_consent.action<>'grant' OR consent_row.id IS NULL OR consent_row.action<>'grant' OR consent_row.source_consent_id<>source_consent.id OR rtrim(consent_row.source_consent_digest)<>rtrim(source_consent.canonical_digest) OR consent_row.revision<>expected_consent_revision OR rtrim(consent_row.canonical_digest)<>expected_consent_digest THEN RAISE EXCEPTION 'Imported material cost consent changed' USING ERRCODE='40001';END IF;
 basis:=public.canonical_imported_material_cost_basis(org,source_value,estimate,job_reference_value,bindings);SELECT * INTO current_row FROM public.canonical_external_material_cost_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate AND external_job_reference=job_reference_value ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF current_row.id IS NOT NULL AND current_row.source_digest=basis->>'sourceDigest' AND current_row.consent_id=consent_row.id THEN RAISE EXCEPTION 'Current imported material cost observation already recorded' USING ERRCODE='22023',CONSTRAINT='imported_material_cost_already_current';END IF;next_revision:=COALESCE(current_row.revision,0)+1;digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'sourceKey',source_value,'estimateId',estimate,'externalJobReference',job_reference_value,'revision',next_revision,'previousId',current_row.id,'consentId',consent_row.id,'sourceDigest',basis->>'sourceDigest','result',basis->'result','actorUserId',actor,'membershipId',(authority->>'membershipId')::uuid,'reason',reason_value,'requestDigest',request_hash));INSERT INTO public.canonical_external_material_cost_observations(organization_id,source_key,estimate_id,external_job_reference,revision,previous_id,consent_id,consent_revision,consent_digest,source_manifest,source_digest,result,scope_note,adoption_boundary,actor_user_id,membership_id,auth_session_id,reason,confirmed,confirmation_version,calculation_version,request_key_hash,request_digest,canonical_digest)VALUES(org,source_value,estimate,job_reference_value,next_revision,current_row.id,consent_row.id,consent_row.revision,rtrim(consent_row.canonical_digest),basis->'sourceManifest',basis->>'sourceDigest',basis->'result',basis->>'scopeNote',basis->>'adoptionBoundary',actor,(authority->>'membershipId')::uuid,session_value,reason_value,TRUE,confirmation_version_value,'m25-imported-material-cost-observation-v1',key_hash,request_hash,digest_value)RETURNING * INTO inserted;RETURN jsonb_build_object('observation',public.canonical_imported_material_cost_projection(inserted)||jsonb_build_object('fresh',TRUE,'advisoryAvailable',(inserted.result->>'availableDimensionCount')::int>0),'replayed',FALSE);END $$;

CREATE FUNCTION public.canonical_imported_material_cost_read(org UUID,actor UUID,role_value TEXT,session_value UUID,source_value TEXT,estimate UUID)RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE source_consent public.canonical_external_material_import_consents%ROWTYPE;consent_row public.canonical_external_material_cost_consents%ROWTYPE;current_row public.canonical_external_material_cost_observations%ROWTYPE;basis JSONB;fresh BOOLEAN;history JSONB;total BIGINT;
BEGIN IF role_value IS NULL OR role_value NOT IN('owner','admin')THEN RAISE EXCEPTION 'Imported material cost review restricted' USING ERRCODE='42501';END IF;PERFORM public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,NULL,FALSE);SELECT * INTO source_consent FROM public.canonical_external_material_import_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;SELECT * INTO consent_row FROM public.canonical_external_material_cost_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;IF source_consent.id IS NULL OR source_consent.action<>'grant' OR consent_row.id IS NULL OR consent_row.action<>'grant' OR consent_row.source_consent_id<>source_consent.id OR rtrim(consent_row.source_consent_digest)<>rtrim(source_consent.canonical_digest)THEN RETURN jsonb_build_object('sourceKey',source_value,'activeConsent',FALSE,'current',NULL,'history','[]'::jsonb,'total',0,'truncated',FALSE,'blockedReason','Cost and purchasing consent is not active for the current source permission.');END IF;SELECT * INTO current_row FROM public.canonical_external_material_cost_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate AND consent_id=consent_row.id ORDER BY revision DESC LIMIT 1;IF NOT FOUND THEN RETURN jsonb_build_object('sourceKey',source_value,'activeConsent',TRUE,'consent',public.canonical_imported_material_cost_consent_projection(consent_row),'current',NULL,'history','[]'::jsonb,'total',0,'truncated',FALSE,'refreshRequired',TRUE);END IF;BEGIN basis:=public.canonical_imported_material_cost_basis(org,source_value,estimate,current_row.external_job_reference,current_row.source_manifest->'bindings');fresh:=current_row.source_digest=basis->>'sourceDigest';EXCEPTION WHEN SQLSTATE 'P0002' THEN fresh:=FALSE;END;SELECT count(*)INTO total FROM public.canonical_external_material_cost_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate AND consent_id=consent_row.id;SELECT COALESCE(jsonb_agg(public.canonical_imported_material_cost_projection(x)||jsonb_build_object('fresh',x.id=current_row.id AND fresh,'advisoryAvailable',x.id=current_row.id AND fresh AND (x.result->>'availableDimensionCount')::int>0,'result',CASE WHEN x.id=current_row.id AND fresh THEN x.result ELSE jsonb_build_object('availableDimensionCount',0,'lines','[]'::jsonb)END)ORDER BY revision DESC),'[]'::jsonb)INTO history FROM(SELECT * FROM public.canonical_external_material_cost_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate AND consent_id=consent_row.id ORDER BY revision DESC LIMIT 20)x;RETURN jsonb_build_object('sourceKey',source_value,'activeConsent',TRUE,'consent',public.canonical_imported_material_cost_consent_projection(consent_row),'current',public.canonical_imported_material_cost_projection(current_row)||jsonb_build_object('fresh',fresh,'advisoryAvailable',fresh AND (current_row.result->>'availableDimensionCount')::int>0,'result',CASE WHEN fresh THEN current_row.result ELSE jsonb_build_object('availableDimensionCount',0,'lines','[]'::jsonb)END),'history',history,'total',total,'truncated',total>20,'refreshRequired',NOT fresh);END $$;

REVOKE ALL ON TABLE public.canonical_external_material_cost_consents,public.canonical_external_material_cost_observations FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_consent_projection(public.canonical_external_material_cost_consents)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_bindings_valid(JSONB)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_match(UUID,TEXT,UUID,TEXT,TEXT,TEXT)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_basis(UUID,TEXT,UUID,TEXT,JSONB)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_projection(public.canonical_external_material_cost_observations)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_consent_read(UUID,UUID,TEXT,UUID,TEXT)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_consent_mutate(UUID,UUID,TEXT,UUID,TEXT,TEXT,TEXT,JSONB)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_observe(UUID,UUID,TEXT,UUID,TEXT,TEXT,TEXT,UUID,TEXT,BIGINT,TEXT,JSONB,TEXT,BOOLEAN,TEXT)FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_imported_material_cost_read(UUID,UUID,TEXT,UUID,TEXT,UUID)FROM PUBLIC;
